        RustLib.instance.api.rust_arc_decrement_strong_count_CoreStore,
    rustArcDecrementStrongCountPtr:
        RustLib.instance.api.rust_arc_decrement_strong_count_CoreStorePtr,
  );

  /// How many Entries, words, and Images a Book holds.
  Future<BookInsightItem> bookInsight({required String id}) => RustLib
      .instance
      .api
      .crateApiStoreCoreStoreBookInsight(that: this, id: id);

  /// Creates a Book.
  Future<BookItem> createBook({required String name}) => RustLib.instance.api
      .crateApiStoreCoreStoreCreateBook(that: this, name: name);

  /// Deletes Books and Entries for good, all of them or none. A Book goes with all its Entries.
  Future<void> deleteForever({
    required List<String> bookIds,
    required List<String> entryIds,
  }) => RustLib.instance.api.crateApiStoreCoreStoreDeleteForever(
    that: this,
    bookIds: bookIds,
    entryIds: entryIds,
  );

  /// Deletes everything in the Trash for good.
  Future<void> emptyTrash() =>
      RustLib.instance.api.crateApiStoreCoreStoreEmptyTrash(that: this);

  /// Writes every Book not in the Trash, with its Entries and Images, into one unencrypted
  /// Archive on the open file `fd`, which it takes over and closes. On Android `fd` comes from
  /// a copy of the picked file's `ParcelFileDescriptor` (`dup().detachFd()`). `exported_at` is in
  /// milliseconds since the Unix epoch.
  ///
  /// On failure or [`ExportJob::cancel`], what was written is not a whole Archive: the caller
  /// deletes the file.
  Future<ExportSummaryItem> exportArchiveToFd({
    required int fd,
    required PlatformInt64 exportedAt,
    required ExportJob job,
  }) => RustLib.instance.api.crateApiStoreCoreStoreExportArchiveToFd(
    that: this,
    fd: fd,
    exportedAt: exportedAt,
    job: job,
  );

  /// Writes the same Archive as [`CoreStore::export_archive_to_fd`] to a new file at `path`,
  /// replacing any file there.
  Future<ExportSummaryItem> exportArchiveToFile({
    required String path,
    required PlatformInt64 exportedAt,
    required ExportJob job,
  }) => RustLib.instance.api.crateApiStoreCoreStoreExportArchiveToFile(
    that: this,
    path: path,
    exportedAt: exportedAt,
    job: job,
  );

  /// How many Entries an Export would write: those not in the Trash, Locked Books included.
  Future<int> exportableEntryCount() => RustLib.instance.api
      .crateApiStoreCoreStoreExportableEntryCount(that: this);

  /// One Book, in the Trash or not.
  Future<BookItem> getBook({required String id}) =>
      RustLib.instance.api.crateApiStoreCoreStoreGetBook(that: this, id: id);

  /// The bytes of a Book's Cover, at full size or as its thumbnail. Fails with `NotFound` when
  /// the Book has no Cover.
  Future<Uint8List> getBookCover({
    required String id,
    required bool thumbnail,
  }) => RustLib.instance.api.crateApiStoreCoreStoreGetBookCover(
    that: this,
    id: id,
    thumbnail: thumbnail,
  );

  /// One Entry.
  Future<EntryItem> getEntry({required String id}) =>
      RustLib.instance.api.crateApiStoreCoreStoreGetEntry(that: this, id: id);

  /// The bytes of one of an Entry's Images, at full size or as its thumbnail.
  Future<Uint8List> getImage({
    required String entryId,
    required String imageId,
    required bool thumbnail,
  }) => RustLib.instance.api.crateApiStoreCoreStoreGetImage(
    that: this,
    entryId: entryId,
    imageId: imageId,
    thumbnail: thumbnail,
  );

  /// A page of the Entries in every Book in `order`, starting after the Entry `after` points
  /// at, or at the top: the Timeline.
  Future<List<EntryItem>> listAllEntries({
    required EntryOrderItem order,
    EntryCursorItem? after,
    required int limit,
  }) => RustLib.instance.api.crateApiStoreCoreStoreListAllEntries(
    that: this,
    order: order,
    after: after,
    limit: limit,
  );

  /// Every Book not locked: the Pinned Books first, then the rest, each with the latest
  /// activity first.
  Future<List<BookItem>> listBooks() =>
      RustLib.instance.api.crateApiStoreCoreStoreListBooks(that: this);

  /// A page of a Book's Entries in `order`, starting after the Entry `after` points at, or at
  /// the top.
  Future<List<EntryItem>> listEntries({
    required String bookId,
    required EntryOrderItem order,
    EntryCursorItem? after,
    required int limit,
  }) => RustLib.instance.api.crateApiStoreCoreStoreListEntries(
    that: this,
    bookId: bookId,
    order: order,
    after: after,
    limit: limit,
  );

  /// Every Locked Book, with the latest activity first.
  Future<List<BookItem>> listLockedBooks() =>
      RustLib.instance.api.crateApiStoreCoreStoreListLockedBooks(that: this);

  /// A page of a Book's Starred Entries, newest first, starting after the Entry `after` points
  /// at, or at the top.
  Future<List<EntryItem>> listStarredEntries({
    required String bookId,
    EntryCursorItem? after,
    required int limit,
  }) => RustLib.instance.api.crateApiStoreCoreStoreListStarredEntries(
    that: this,
    bookId: bookId,
    after: after,
    limit: limit,
  );

  /// Every Book and Entry in the Trash, the one deleted most recently first.
  Future<List<TrashedItem>> listTrash() =>
      RustLib.instance.api.crateApiStoreCoreStoreListTrash(that: this);

  /// Moves Entries to another Book, all of them or none. Each keeps its ID, content, and times.
  Future<void> moveEntries({
    required List<String> ids,
    required String bookId,
  }) => RustLib.instance.api.crateApiStoreCoreStoreMoveEntries(
    that: this,
    ids: ids,
    bookId: bookId,
  );

  /// The earliest day with an Entry in the Timeline, as `YYYY-MM-DD` in local time
  /// `utc_offset_minutes` east of UTC; none when the Timeline has no Entry.
  Future<String?> oldestTimelineDay({required int utcOffsetMinutes}) =>
      RustLib.instance.api.crateApiStoreCoreStoreOldestTimelineDay(
        that: this,
        utcOffsetMinutes: utcOffsetMinutes,
      );

  /// Rebuilds the lists and the search index from the encrypted Entries.
  Future<void> rebuildIndex() =>
      RustLib.instance.api.crateApiStoreCoreStoreRebuildIndex(that: this);

  /// Removes a Book's Cover.
  Future<void> removeBookCover({required String id}) => RustLib.instance.api
      .crateApiStoreCoreStoreRemoveBookCover(that: this, id: id);

  /// Renames a Book.
  Future<void> renameBook({required String id, required String name}) => RustLib
      .instance
      .api
      .crateApiStoreCoreStoreRenameBook(that: this, id: id, name: name);

  /// Takes Books and Entries out of the Trash, all of them or none. An Entry whose Book is in
  /// the Trash and not restored with it goes to the Book `others_to`; with none, its Book is
  /// restored too.
  Future<void> restore({
    required List<String> bookIds,
    required List<String> entryIds,
    String? othersTo,
  }) => RustLib.instance.api.crateApiStoreCoreStoreRestore(
    that: this,
    bookIds: bookIds,
    entryIds: entryIds,
    othersTo: othersTo,
  );

  /// Saves a new Entry, or a change to one, and returns it as stored.
  Future<EntryItem> saveEntry({required EntryDraftItem draft}) => RustLib
      .instance
      .api
      .crateApiStoreCoreStoreSaveEntry(that: this, draft: draft);

  /// Entries in which every word typed starts a word, newest Entry date first, within one Book
  /// if `book_id` is given. In snippets, each match is between U+E000 and U+E001.
  Future<SearchPage> search({
    required String query,
    String? bookId,
    required int limit,
    required int offset,
  }) => RustLib.instance.api.crateApiStoreCoreStoreSearch(
    that: this,
    query: query,
    bookId: bookId,
    limit: limit,
    offset: offset,
  );

  /// Gives a Book a new Cover from the bytes of its full-size image and its thumbnail, in
  /// place of the one it had.
  Future<void> setBookCover({
    required String id,
    required List<int> full,
    required List<int> thumbnail,
  }) => RustLib.instance.api.crateApiStoreCoreStoreSetBookCover(
    that: this,
    id: id,
    full: full,
    thumbnail: thumbnail,
  );

  /// Sets a Book's Description. An empty one removes it.
  Future<void> setBookDescription({
    required String id,
    required String description,
  }) => RustLib.instance.api.crateApiStoreCoreStoreSetBookDescription(
    that: this,
    id: id,
    description: description,
  );

  /// Keeps a Book out of the Timeline on this device, or puts it back in.
  Future<void> setBookInTimeline({
    required String id,
    required bool inTimeline,
  }) => RustLib.instance.api.crateApiStoreCoreStoreSetBookInTimeline(
    that: this,
    id: id,
    inTimeline: inTimeline,
  );

  /// Locks or unlocks Books, all of them or none. Locking also unpins them. A lock is not
  /// encryption: the Books' Entries are sealed the same either way.
  Future<void> setBooksLocked({
    required List<String> ids,
    required bool locked,
  }) => RustLib.instance.api.crateApiStoreCoreStoreSetBooksLocked(
    that: this,
    ids: ids,
    locked: locked,
  );

  /// Pins or unpins Books on this device. Fails with `TooManyPinned`, pinning none of them, if
  /// that would make more Pinned Books than allowed.
  Future<void> setBooksPinned({
    required List<String> ids,
    required bool pinned,
  }) => RustLib.instance.api.crateApiStoreCoreStoreSetBooksPinned(
    that: this,
    ids: ids,
    pinned: pinned,
  );

  /// Stars or unstars Entries, all of them or none. Starring is not editing: the Entries do
  /// not change.
  Future<void> setEntriesStarred({
    required List<String> ids,
    required bool starred,
  }) => RustLib.instance.api.crateApiStoreCoreStoreSetEntriesStarred(
    that: this,
    ids: ids,
    starred: starred,
  );

  /// Sets how many days the Trash keeps what is deleted, 7, 30, or 90, and deletes for good at
  /// once what was deleted longer ago than that. Other numbers fail with `Invalid`.
  Future<void> setTrashDays({required int days}) => RustLib.instance.api
      .crateApiStoreCoreStoreSetTrashDays(that: this, days: days);

  /// The days from `from` to `to`, both `YYYY-MM-DD` and both included, with an Entry in the
  /// Timeline, in local time `utc_offset_minutes` east of UTC, earliest first.
  Future<List<String>> timelineDays({
    required String from,
    required String to,
    required int utcOffsetMinutes,
  }) => RustLib.instance.api.crateApiStoreCoreStoreTimelineDays(
    that: this,
    from: from,
    to: to,
    utcOffsetMinutes: utcOffsetMinutes,
  );

  /// Moves a Book to the Trash, with its Entries. It is no longer pinned or kept out of the
  /// Timeline.
  Future<void> trashBook({required String id}) =>
      RustLib.instance.api.crateApiStoreCoreStoreTrashBook(that: this, id: id);

  /// How many items the Trash holds.
  Future<int> trashCount() =>
      RustLib.instance.api.crateApiStoreCoreStoreTrashCount(that: this);

  /// How many days the Trash keeps what is deleted: 7, 30, or 90.
  Future<int> trashDays() =>
      RustLib.instance.api.crateApiStoreCoreStoreTrashDays(that: this);

  /// Moves Entries to the Trash, all of them or none.
  Future<void> trashEntries({required List<String> ids}) => RustLib.instance.api
      .crateApiStoreCoreStoreTrashEntries(that: this, ids: ids);

  /// Fires after every commit, until the stream is cancelled.
  Stream<StoreChange> watch() =>
      RustLib.instance.api.crateApiStoreCoreStoreWatch(that: this);
}

